// <auto-generated> by cs/tools/ts2cs.mjs from src/sim/character.ts, then fixed by hand where it says so.
// Character creation: who you are, chosen before the world begins.
//
//   name        what you're called (NAME_MAX letters, spaces, hyphens and apostrophes).
//   profession  one of story.ts STORY_JOBS: what you did before. It starts some skills at a level
//               (PROFESSIONS: xp of XP_PER_LEVEL a level), puts a few things in your bag, and
//               costs or gives points (a soldier costs; a student has time on their hands).
//   traits      chosen from CHOOSABLE, each with a cost (TRAIT_COST): good ones cost points,
//               bad ones give them back. You can't end below zero (characterProblem).
// The character becomes the first survivor of a generated world (createWorld): yours in a solo
// start, the first of the three in a group. Nothing here touches the sim RNG.
#nullable disable warnings
namespace LoonieRoo.Sim;

public static partial class CharacterMod
{

    public const int NAME_MAX = 16;

    /// <summary>Points everyone starts with, before their profession and traits.</summary>
    public const int START_POINTS = 4;

    /// <summary>By STORY_JOBS entry.</summary>
    public static readonly JsRecord<Profession> PROFESSIONS = new() { ["a nurse"] = new() { skills = new() { doctor = 3 }, kit = ["medicine", "bandage"], points = -2, about = "patches people up" }, ["a mechanic"] = new() { skills = new() { craft = 3, build = 1 }, kit = ["hammer", "scrap"], points = -2, about = "makes things, fixes things" }, ["a teacher"] = new() { skills = new() { research = 3 }, kit = ["book"], points = 0, about = "reads, and works things out" }, ["a farmer"] = new() { skills = new() { farm = 3, hunt = 1 }, kit = ["food", "food"], points = -2, about = "grows food" }, ["a soldier"] = new() { skills = new() { guard = 3 }, kit = ["armour"], points = -4, about = "fights, in armour" }, ["a cook"] = new() { skills = new() { cook = 3 }, kit = ["food", "food", "food"], points = 0, about = "cooks, and brought food" }, ["a police officer"] = new() { skills = new() { guard = 2 }, kit = ["gun", "ammo"], points = -4, about = "fights, with a gun" }, ["a carpenter"] = new() { skills = new() { build = 3 }, kit = ["hammer", "wood", "wood"], points = -2, about = "builds" }, ["a paramedic"] = new() { skills = new() { doctor = 2 }, kit = ["medkit", "bandage"], points = -2, about = "patches people up, with a kit" }, ["a lorry driver"] = new() { skills = new() { haul = 3, scout = 1 }, kit = ["fuel"], points = 0, about = "carries, and knows the roads" }, ["an electrician"] = new() { skills = new() { craft = 2, build = 1 }, kit = ["scrap", "scrap"], points = -1, about = "makes things" }, ["a priest"] = new() { skills = new() { clean = 1 }, kit = [], points = 2, about = "little to offer but faith" }, ["a shop clerk"] = new() { skills = new() { scavenge = 2, haul = 1 }, kit = ["food"], points = 0, about = "knows where things are kept" }, ["a student"] = new() { skills = new(), kit = [], points = 4, about = "nothing much yet" } };

    /// <summary>Traits you can pick, and what each costs (negative: gives points back).</summary>
    public static readonly JsRecord<double> TRAIT_COST = new() { ["tough"] = 4, ["quick"] = 4, ["graceful"] = 3, ["greenThumb"] = 2, ["cheerful"] = 2, ["lazy"] = -3, ["gloomy"] = -2, ["clumsy"] = -2 };

    public static readonly List<string> CHOOSABLE = Js.ObjectKeys(TRAIT_COST);

    /// <summary>Pairs you can't have both of.</summary>
    public static readonly List<List<string>> OPPOSED = [["cheerful", "gloomy"], ["graceful", "clumsy"]];

    public static Profession? professionOf(double job)
    {
        var name = StoryMod.STORY_JOBS[Js.Idx(job)];
        return (name == null) ? null : PROFESSIONS[Js.Idx(name)];
    }

    /// <summary>Points left with this profession and these traits.</summary>
    public static double pointsLeft(Character c)
    {
        return (START_POINTS + (professionOf(c.job)?.points ?? 0)) - c.traits.reduce((sum, t) => sum + (TRAIT_COST[Js.Idx(t)] ?? 0), 0);
    }

    /// <summary>Tidies a typed name: letters, spaces, hyphens, apostrophes; at most NAME_MAX.</summary>
    public static string cleanName(string name)
    {
        return name.replace(/*TODO regex /[^\p{L} '-]/gu*/null, "").replace(/*TODO regex /\s+/g*/null, " ").trim().slice(0, NAME_MAX).trim();
    }

    /// <summary>What's wrong with a character, or null if it's fine.</summary>
    public static string? characterProblem(Character c)
    {
        if (cleanName(c.name) == "")
        {
            return "needs a name";
        }
        if (!Js.T(professionOf(c.job)))
        {
            return "no such profession";
        }
        if (Js.Set(c.traits).size != c.traits.length)
        {
            return "a trait twice";
        }
        if (c.traits.some((t) => TRAIT_COST[Js.Idx(t)] == null))
        {
            return "a trait you can't choose";
        }
        foreach (var (a, b) in Js.Iter(OPPOSED))
        {
            if (c.traits.includes(a) && c.traits.includes(b))
            {
                return $"can't be both {Js.Str(a)} and {Js.Str(b)}";
            }
        }
        if (pointsLeft(c) < 0)
        {
            return "not enough points";
        }
        return null;
    }

    /// <summary>Makes a survivor this character: name, past, skills, traits, and their kit (bagged if you control them).</summary>
    public static void applyCharacter(SimState state, Survivor s, Character c)
    {
        var p = professionOf(c.job)!;
        s.name = cleanName(c.name);
        s.story.job = c.job;
        s.traits = (c.traits).ToList();
        foreach (var (type, level) in Js.Iter(Js.ObjectEntries(p.skills)))
        {
            s.xp[Js.Idx(type)] = level * Skills.XP_PER_LEVEL;
        }
        var yours = state.control?.survivorId == s.id;
        foreach (var kind in Js.Iter(p.kit))
        {
            var item = Items.spawnItem(state, kind, s.pos.x, s.pos.y);
            if (Js.T(yours))
            {
                Inventory.stow(state, s, item);
            }
        }
    }
}
